def _validate_bucket_size(bucket_size):
    if (
        not isinstance(bucket_size, int)
        or isinstance(bucket_size, bool)
        or bucket_size <= 0
    ):
        raise InvalidBucketSizeError(
            "bucket_size 必须为大于 0 的整数秒", None
        )

def time_stats(self, filters, bucket_size,
               page_size=DEFAULT_PAGE_SIZE, cursor=None):
    """按固定宽度 UTC 秒区间分桶的分页统计。

    区间从 Unix 纪元对齐
    （``bucket_start = timestamp // bucket_size * bucket_size``）、
    左闭右开，时间窗本身仍左闭右闭，因此每笔匹配交易只进入一个区间，
    时间窗端点与区间边界都不会漏计或重复。只返回非空区间并按
    bucket_start 升序分页。

    返回 {groups, total_groups, next_cursor}；每组含 bucket_start、
    bucket_end_exclusive、total_count、total_amount、avg_amount
    （起止为 UTC 秒整数，金额为十进制整数字符串，平均值向下取整）。
    """
    self._validate_bucket_size(bucket_size)
    self._validate_page_size(page_size)

    totals = {}
    counts = {}
    for record in self._records:
        if not _matches(record, filters):
            continue
        timestamp = record["timestamp"]
        # 整除对齐纪元：同一区间内任意 timestamp 都映射到唯一 bucket_start
        bucket_start = (timestamp // bucket_size) * bucket_size
        totals[bucket_start] = totals.get(bucket_start, 0) + int(
            record["amount"]
        )
        counts[bucket_start] = counts.get(bucket_start, 0) + 1

    bucket_starts = sorted(totals)
    total_groups = len(bucket_starts)

    start = 0
    if cursor is not None:
        after_bucket_start = decode_time_stats_cursor(
            cursor, filters, bucket_size
        )
        # keyset 续页：bucket_start 严格大于 marker 的第一个位置。
        # marker 位于两个现存区间之间也安全（bisect 取下一键），
        # 不会跳过或重复。
        start = bisect.bisect_right(bucket_starts, after_bucket_start)

    end = start + page_size
    page_starts = bucket_starts[start:end]
    groups = [
        {
            "bucket_start": bucket_start,
            "bucket_end_exclusive": bucket_start + bucket_size,
            "total_count": counts[bucket_start],
            "total_amount": str(totals[bucket_start]),
            "avg_amount": str(
                totals[bucket_start] // counts[bucket_start]
            ),
        }
        for bucket_start in page_starts
    ]
    if end < total_groups:
        next_cursor = encode_time_stats_cursor(
            filters, bucket_size, page_starts[-1]
        )
    else:
        next_cursor = None

    return {
        "groups": groups,
        "total_groups": total_groups,
        "next_cursor": next_cursor,
    }

